import React, { useState } from 'react'
import './home.scss';
import '../../styles/animate.scss';
import splash_kingpin from '../img/splash_kingpin_og.png';
import splash_kingpin_overlay from '../img/splash_kingpin_overlay.png';

function Home() {
  const [splashLoaded, setSplashLoaded] = useState(false);
  const [overlayLoaded, setOverlayLoaded] = useState(false);

  return (
    <div className='body'>
      <div className='splash'>
        <img
          src={splash_kingpin}
          className={splashLoaded ? 'splash_img splash_img_real animate_focusIn' : 'splash_img splash_img_real'}
          alt='landing page splash art'
          onLoad={() => setSplashLoaded(true)}
          fetchpriority='high'
        />
        {splashLoaded && <img
          src={splash_kingpin_overlay}
          className={splashLoaded ? 'splash_img animate_pulseFull' : 'splash_img'}
          alt='landing page splash art overlay'
          onLoad={() => setOverlayLoaded(true)}
          fetchpriority='low'
        />}
      </div>
    </div>
  );
}

export default Home;