import React, { PropsWithChildren } from 'react';
import classnames from 'classnames';
import './index.scss';

type TagAppearances = 'filled' | 'outlined' | 'two-tone' | 'two-tone-border';

type TagShapes = 'default' | 'round';

type TagTypes =
    'koranin' | 'alcerium' | 'castorix' | 'lyrisius' | 'lysande' | 'valterre'
    | 'creature' | 'mineral' | 'plant'
    | 'system';

type TagProps = {
    appearance?: TagAppearances,
    onClick?: () => void,
    shape?: TagShapes,
    type?: TagTypes | string,
}

const Tag = (props: PropsWithChildren<TagProps>) => {
    const {
        appearance,
        children,
        onClick,
        shape,
        type,
    } = props;

    const sharedProps = {
        className: classnames(
            'tag',
            `${onClick && 'onClick'}`,
            shape ? `shape_${shape}` : 'shape_default',
        )
    }

    return (
        <div
            {...sharedProps}
            style={{
                backgroundColor: `${appearance === 'outlined' ? 'transparent' : `color-mix(in srgb, rgba(var(--${type}), 1), transparent ${appearance?.includes('two-tone') ? '80%' : '0%'})`}`,
                border: `${(appearance === 'outlined' || appearance === 'two-tone-border') ? `1px solid rgba(var(--${type ? type : 'text-main'}), 1)` : 'none'}`,
                color: `${appearance === 'filled' ? 'rgba(var(--text-secondary), 1)' : (appearance?.includes('two-tone') ? `rgba(var(--${type}), 1)` : (type ? `rgba(var(--${type}), 1)` : 'rgba(var(--text-secondary), 1)'))}`,
                gap: '4px',
                cursor: `${onClick ? 'pointer' : 'default'}`
            }}
            onClick={onClick}
        >
            {children || (type ? type : 'Tag')}
        </div>
    );
}

export default Tag;
