import React, { PropsWithChildren, useEffect, useState } from 'react';
import './index.scss';

type PaginationProps = {
    data: Array<any>,
    getCurrPage: any,
    paginationOptions?: Array<string | number>,
}

const Pagination = (props: PropsWithChildren<PaginationProps>) => {
    const {
        data,
        getCurrPage,
        paginationOptions,
    } = props;

    const [numPages, setNumPages] = useState(paginationOptions ? [paginationOptions[0]] : [10, 20, 30]);
    const [numPagesIndexed, setNumPagesIndexed] = useState<Array<string | number>>(numPages);
    const [selectedNumPages, setSelectedNumPages] = useState<string | null>(paginationOptions ? [paginationOptions[0]]?.toString() : [10, 20, 30]?.map((i) => i + ' / page')[0]);

    const [currPage, setCurrPage] = useState<number>(1);
    const [lastPage, setLastPage] = useState<number>(1);
    const [firstIndex, setFirstIndex] = useState<number>(0);
    const [secondIndex, setSecondIndex] = useState<number>(0);

    const calcNumPages = (data: Array<any>, rows: number) => {
        const numPages = [];
        const num = Math.ceil(data?.length / rows);
        for (let i = 1; i <= num; i++) {
            numPages?.push(i);
        }
        return numPages;
    }

    useEffect(() => {
        setNumPagesIndexed(numPages);
        setLastPage(Number(numPages?.slice(-1)[0]));
    }, [numPages]);

    useEffect(() => {
        setCurrPage(1);
    }, [selectedNumPages, data]);

    useEffect(() => {
        if (selectedNumPages?.match(/\d+/) !== null) {
            const numPages = calcNumPages([...data], Number(selectedNumPages?.match(/\d+/)));
            setNumPages([...numPages]);
        }
    }, [currPage, selectedNumPages, data]);

    useEffect(() => {
        if (numPages?.length > 6) {
            if (currPage < 6) {
                setNumPagesIndexed([...numPages]?.slice(0, 5)?.concat('...')?.concat([...numPages]?.slice(-1)[0]));
            } else if (currPage > (lastPage - 4)) {
                setNumPagesIndexed([...numPages]?.slice(0, 1)?.concat('...')?.concat([...numPages]?.slice(([...numPages]?.length - 5), Number([...numPages]?.slice(-1)[0]))));
            } else {
                setNumPagesIndexed([...numPages]?.slice(0, 1)?.concat(' ...')?.concat([...numPages]?.slice(currPage - 3, currPage + 2))?.concat('... ')?.concat([...numPages]?.slice(-1)[0]));
            }
        }
    }, [currPage, selectedNumPages, data]);

    useEffect(() => {
        if (selectedNumPages?.match(/\d+/) !== null) {
            const partition = Number(selectedNumPages?.match(/\d+/));
            setFirstIndex((currPage * partition) - (partition - 1));
            setSecondIndex((currPage === lastPage ? ((currPage * partition !== data?.length) ? data?.length : (currPage * partition)) : (currPage * partition)));
        }
    }, [currPage, lastPage, numPages, selectedNumPages, data?.length]); //eslint-disable-line

    useEffect(() => {
        getCurrPage(currPage);
    }, [currPage]);

    return (
        <div className='pagination'>
            <div className='pagination_info'>
                <span>{`${firstIndex} - ${secondIndex} of ${data?.length} entries`}</span>
            </div>
            <div className='pagination_pages'>
                <span style={{ cursor: `${currPage === 1 ? 'not-allowed' : 'pointer'}` }}>
                    <span
                        onClick={() => currPage !== 1 && setCurrPage(currPage - 1)}
                    //disabled={currPage === 1}
                    >
                    </span>
                </span>
                <div className='pagination_pages_node_container'>
                    {numPagesIndexed && numPagesIndexed?.length > 0 && numPagesIndexed?.map((page) =>
                        <span
                            key={page}
                            className={currPage === page ? 'pagination_pages_node_active pagination_pages_node' : (page?.toString()?.replace(/\s+/g, '') !== '...' ? 'pagination_pages_node_inactive pagination_pages_node' : 'pagination_pages_node')}
                            onClick={() => (page !== currPage && page !== '...') && setCurrPage(Number(page))}
                        >
                            {page}
                        </span>
                    )}
                </div>
                <span style={{ cursor: `${currPage === lastPage ? 'not-allowed' : 'pointer'}` }}>
                    <span
                        onClick={() => currPage !== lastPage && setCurrPage(currPage + 1)}
                    //disabled={currPage === lastPage}
                    >
                    </span>
                </span>
            </div>
        </div>
    );
}

export default Pagination;
