import React, { PropsWithChildren, useEffect, useState } from 'react';
import './index.scss';

type SearchProps = {
    data: Array<object> | Array<string>,
    filteredData: any,
    placeholder?: string,
    searchKey?: string,
}

const Search = (props: PropsWithChildren<SearchProps>) => {
    const {
        data,
        filteredData,
        placeholder,
        searchKey,
    } = props;

    const [searchQuery, setSearchQuery] = useState<string>('');
    const keys: any[] = [];

    if (data && data?.length && typeof data[0] === 'object' && data[0] !== null && !searchKey) {
        data?.map((item) => (
            Object.entries(item)?.map(([key]) => {
                if (keys?.length === Object.keys(item)?.length) {
                    return 0;
                } else {
                    keys?.push(key?.toString());
                }
                return 0;
            })
        ));
    }

    const onSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
        setSearchQuery(e.target.value);
    }

    useEffect(() => {
        const dataCopy = [...data];
        if (searchQuery?.length) {
            if (typeof data[0] === 'object' && data[0] !== null) {
                return filteredData(dataCopy?.filter((item: any = {}) =>
                    !searchKey ? keys?.some((key) =>
                        item[key]?.toString()?.toLowerCase()?.includes(searchQuery?.toString()?.toLowerCase())
                    ) : item[searchKey]?.toString()?.toLowerCase()?.includes(searchQuery?.toString()?.toLowerCase())
                ))
            } else {
                return filteredData(dataCopy?.filter((item) =>
                    item?.toString()?.toLowerCase()?.includes(searchQuery?.toLowerCase())
                ));
            }
        } else {
            return filteredData(dataCopy);
        }
    }, [searchQuery]); //eslint-disable-line

    useEffect(() => {
        setSearchQuery('');
    }, [data?.length]); //eslint-disable-line

    return (
        <div className='search'>
            <div className='search_icon'></div>
            <input
                type='search'
                placeholder={placeholder || 'Search'}
                onChange={(e) => onSearch(e)}
                value={searchQuery}
                className='search_field'
            />
        </div>
    );
}

export default Search;
