import React, { PropsWithChildren } from 'react';
import { AlceriumIcon, CastorixIcon, LyrisiusIcon, LysandeIcon, ValterreIcon } from '../../assets/index';
import './index.scss';

type SectorSelectorProps = {
    active: 'Alcerium' | 'Castorix' | 'Lyrisius' | 'Lysande' | 'Valterre',
    backgroundColor?: string,
}

const SectorSelector = (props: PropsWithChildren<SectorSelectorProps>) => {
    const {
        active,
        backgroundColor,
    } = props;

    const selector = [
        {
            name: 'alcerium',
            icon: AlceriumIcon,
        },
        {
            name: 'castorix',
            icon: CastorixIcon,
        },
        {
            name: 'valterre',
            icon: ValterreIcon,
        },
        {
            name: 'lyrisius',
            icon: LyrisiusIcon,
        },
        {
            name: 'lysande',
            icon: LysandeIcon,
        },
    ];

    const onRedirect = (url: string) => {
        window.location.href = url;
    }

    return (
        <div
            className='sectorSelector'
            style={{ background: `${backgroundColor || 'white'}` }}
        >
            {selector?.map((sector, index) =>
                <img
                    key={index}
                    src={sector?.icon}
                    alt={`${sector?.name} icon`}
                    className={`${sector?.name?.toLowerCase() === active?.toLowerCase() && 'sectorSelector_active'}`}
                    onClick={() => onRedirect(`/kingpin/world/${sector['name']}`)}
                />
            )}
        </div>
    );
}

export default SectorSelector;
