import React, { lazy, useState, useEffect, Suspense } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import './character.scss';
import '../../styles/animate.scss';
import { CharacterSelect, CharacterSelectHand, AlceriumSVG, CastorixSVG, LysandeSVG, LyrisiusSVG, ValterreSVG, CharacterBgOverlay } from '../../assets';
const CharacterSelection = lazy(() => import('../index').then((module) => ({ default: module.CharacterSelection })));

const Character = () => {
    const [loaded, setLoaded] = useState<boolean>(false);
    const [activeSector, setActiveSector] = useState<string | null>(null);

    const getRandomSector = (arr: Array<string>) => {
        const randomIndex = Math.floor(Math.random() * arr.length);
        return arr[randomIndex];
    }

    const onClick = (sector: string) => {
        setActiveSector(sector);
    }

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setLoaded(true);
                    observer.disconnect();
                }
            },
            { threshold: 0.5 }
        )

        const target = document.getElementById('lazy-load-target');
        if (target) {
            observer.observe(target);
        }
        return () => observer.disconnect();
    }, [activeSector]);

    AOS.init({
        duration: 1200,
    });

    const sector_icons = [
        {
            name: 'alcerium',
            active: <AlceriumSVG width='80px' stroke='#FFD79E' />,
            inactive: <AlceriumSVG width='80px' stroke='#FCC372' />,
            style: { transformOrigin: 'top right', transform: 'rotate(80deg)', margin: '-48.5% 0 0 -22%', transition: 'all 0.4s ease-in-out' },
        },
        {
            name: 'castorix',
            active: <CastorixSVG height='80px' stroke='#FFD79E' />,
            inactive: <CastorixSVG height='80px' stroke='#FCC372' />,
            style: { transformOrigin: 'top right', transform: 'rotate(40deg)', margin: '-50% 0 0 -21%', transition: 'all 0.4s ease-in-out' },
        },
        {
            name: 'valterre',
            active: <ValterreSVG height='80px' stroke='#FFD79E' />,
            inactive: <ValterreSVG height='80px' stroke='#FCC372' />,
            style: { transformOrigin: 'top right', margin: '-51.7% 0 0 -21%', transition: 'all 0.4s ease-in-out' },
        },
        {
            name: 'lyrisius',
            active: <LyrisiusSVG height='80px' stroke='#FFD79E' />,
            inactive: <LyrisiusSVG height='80px' stroke='#FCC372' />,
            style: { transformOrigin: 'top right', transform: 'rotate(-38deg)', margin: '-53% 0 0 -22.2%', transition: 'all 0.4s ease-in-out' },
        },
        {
            name: 'lysande',
            active: <LysandeSVG width='80px' stroke='#FFD79E' />,
            inactive: <LysandeSVG width='80px' stroke='#FCC372' />,
            style: { transformOrigin: 'top right', transform: 'rotate(-79deg)', margin: '-53.1% 0 0 -23.8%', transition: 'all 0.4s ease-in-out' },
        },
    ];

    useEffect(() => {
        setActiveSector(getRandomSector(['alcerium', 'castorix', 'valterre', 'lyrisius', 'lysande']));
    }, []);

    return (
        <div className='character'>
            {}
            <img
                src={CharacterBgOverlay}
                alt='chara_bg'
                className='character_overlap'
            />
            <div className='character_body'>
                <div className='character_filter'>
                    <img
                        src={CharacterSelect}
                        alt='character select comp'
                        className='character_filter'
                    />
                    <div className='character_filter_overlap'>
                        {activeSector && <img
                            src={CharacterSelectHand}
                            alt='character select comp'
                            className='character_filter_overlap_hand'
                            style={sector_icons?.find((i) => i?.name === activeSector)?.style}
                        />}
                    </div>
                    <div className='character_filter_overlap'>
                        {sector_icons?.map((sector) =>
                            <div className={`character_filter_overlap_icon character_filter_overlap_icon_${sector?.name} ${sector?.name === activeSector && 'character_filter_overlap_icon_active'}`}>
                                <button onClick={() => onClick(sector?.name)}>
                                    {sector?.name === activeSector ? sector?.active : sector?.inactive}
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>
            <span style={{ color: '#FCC372' }}>
                {`The mages of ${activeSector}`.toUpperCase()}
            </span>
            <br></br><br></br>
            <div
                id='lazy-load-target'
                className='character_details'
            >
                {loaded
                    && <Suspense fallback={<div>Loading...</div>}>
                        <div
                            key={Math.random()}
                            className='animate_shimmer'
                        // style={{ height: '376px' }}
                        >
                            {activeSector !== null && <CharacterSelection sector={activeSector} />}
                        </div>
                    </Suspense>
                }
            </div>
        </div>
    );
}

export default Character;