import React, { PropsWithChildren } from 'react';
import { Arrow } from '../../../assets';
import './index.scss';

type SlideshowButtonsProps = {
    direction: 'left' | 'right',
    onSlide: () => void,
}

const SlideshowButtons = (props: PropsWithChildren<SlideshowButtonsProps>) => {
    const {
        direction,
        onSlide,
    } = props;

    return (
        <button
            onClick={onSlide}
            className={`slideshow_button ${direction}`}
        >
            <img
                src={Arrow}
                alt='arrow'
                className={`arrow_${direction}`}
            />
        </button>
    )
}

export default SlideshowButtons;