import React, { PropsWithChildren } from 'react';
import { NavLink } from 'react-router-dom';
import './index.scss';

type RouteProps = {
    path: string,
    name: string,
}

type NavProps = {
    logo: string,
    routes: Array<RouteProps>,
}

const Nav = (props: PropsWithChildren<NavProps>) => {
    const {
        logo,
        routes,
    } = props;

    return (
        <div className='nav'>
            <NavLink
                to='/'
                style={{ textDecoration: 'none' }}
            >
                <img src={logo} alt='site logo' className='nav_logo' />
            </NavLink>
            {routes?.map((route, index) =>
                <NavLink
                    key={index}
                    to={route.path}
                    style={{ textDecoration: 'none' }}
                    className='nav_link'
                >
                    {route.name}
                </NavLink>
            )}
        </div>
    );
}

export default Nav;