import React, { PropsWithChildren, useState } from 'react';
import { Title } from '..';
import './index.scss';

type ItemProps = {
    title: string,
    description: string,
}

type AccordionProps = {
    color?: string,
    items: Array<ItemProps>,
    overflowHeight?: string,
    titleColor?: string,
    titleSize?: 'h1' | 'h2' | 'h3' | 'h4',
    width?: string,
}

const Accordion = (props: PropsWithChildren<AccordionProps>) => {
    const {
        color,
        items,
        overflowHeight,
        titleColor,
        titleSize,
        width,
    } = props;

    const [activeIndex, setActiveIndex] = useState(0);

    const onClick = (index: number) => {
        setActiveIndex(index);
    }

    return (
        <div
            className='accordion'
            style={{ color: `${color ? color : 'var(--text-main)'}` }}
        >
            <div
                className='accordion_container'
                style={{ width: `${width ? width : '50vw'}` }}
            >
                {items?.map((item, index) =>
                    <div key={index} className='accordion_section'>
                        <div
                            className={`${index === activeIndex && 'accordion_section_title_active'} accordion_section_title`}
                            onClick={() => onClick(index)}
                        >
                            <Title
                                size={titleSize ? titleSize : 'h2'}
                                color={titleColor ? titleColor : 'var(--text-main)'}
                            >
                                {(index === activeIndex ? '✦ ' : '⟡ ') + item?.title}
                            </Title>
                        </div>
                        <div
                            className={`${index === activeIndex ? 'accordion_section_description_open' : 'accordion_section_description_closed'} accordion_section_description`}
                            style={{
                                height: `${index === activeIndex && overflowHeight ? overflowHeight : ''}`,
                                paddingLeft: `${titleSize === 'h3' ? '16px' : '22px'}`,
                                marginLeft: `${titleSize === 'h3' ? '9px' : '12px'}`,
                                borderLeft: `1.5px solid ${titleColor ? titleColor : 'rgba(255, 255, 255, 0.5)'}`,
                                overflowY: `${index === activeIndex && overflowHeight ? 'scroll' : 'auto'}`
                            }}
                        >
                            {typeof item?.description === 'string'
                                ? item?.description?.split('\n')?.map((i, index) =>
                                    <div key={index}>
                                        {i}{index < item?.description?.split('\n')?.length - 1}
                                    </div>
                                ) : ''
                                // Array.isArray(item?.description) && item['description'].map((i: any, index: number) =>
                                //     <div key={index}>{i}</div>
                                // )
                            }
                        </div>
                    </div>
                )}
            </div>
        </div>
    )
}

export default Accordion;