import React, { lazy, Suspense, useEffect } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import './index.css';
import './App.css';
import './styles/animate.scss';
import Home from './pages/home/Home.js';

import { JokerIcon } from './assets';
import { Footer, Nav } from './components/index';
import routes from './pages/routes/index';

const About = lazy(() => import('./pages/index').then((module) => ({ default: module.About })));
const Character = lazy(() => import('./pages/index').then((module) => ({ default: module.Character })));
const Lexicon = lazy(() => import('./pages/index').then((module) => ({ default: module.Lexicon })));
const Sector = lazy(() => import('./pages/index').then((module) => ({ default: module.Sector })));
const World = lazy(() => import('./pages/index').then((module) => ({ default: module.World })));

const App = () => {
  useEffect(() => {
    document.title = 'kingpin';
  }, []);

  return (
    <div className='App'>
      <BrowserRouter basename='/kingpin'>
        <Nav logo={JokerIcon} routes={routes} />
        <Suspense fallback={<div>Loading...</div>}>
          <Routes>
            <Route path='/' element={<Home />} />
            <Route path='/world' element={<World />} />
            <Route path='/world/alcerium' element={<Sector name='Alcerium' />} />
            <Route path='/world/castorix' element={<Sector name='Castorix' />} />
            <Route path='/world/valterre' element={<Sector name='Valterre' />} />
            <Route path='/world/lyrisius' element={<Sector name='Lyrisius' />} />
            <Route path='/world/lysande' element={<Sector name='Lysande' />} />
            <Route path='/character' element={<Character />} />
            {/* <Route path='/joker' element={<Joker />} /> */}
            <Route path='/lexicon' element={<Lexicon />} />
            <Route path='/about' element={<About />} />
          </Routes>
        </Suspense>
      </BrowserRouter>
      <Footer />
    </div>
  );
}

export default App;