import React, { PropsWithChildren, useState, useEffect, useLayoutEffect } from 'react';
import { useLocation } from 'react-router-dom';
import './sector.scss';
import SectorConfig from './Config';
import { SectorSelector, Slideshow, Title } from '../../../components';
import { ClubSVG, DiamondSVG, HeartSVG, SpadeSVG } from '../../../assets/index';

type SectorProps = {
    name: 'Alcerium' | 'Castorix' | 'Lyrisius' | 'Lysande' | 'Valterre',
}

const Sector = (props: PropsWithChildren<SectorProps>) => {
    const {
        name,
    } = props;

    const [sector, setSector] = useState<any>({});
    const location = useLocation();

    useLayoutEffect(() => {
        window.scrollTo(0, 0);
        setSector({});
    }, [location.pathname]);

    useEffect(() => {
        setSector(SectorConfig?.find((sector: any) => sector?.name === name));
    }, [name]);

    const places = sector['places']?.map((place: any) =>
        <div
            key={place?.id}
            style={{
                height: '80%',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between'
            }}
        >
            <Title size='h2'>{place?.name}</Title>
            <span>{place?.description}</span>
            <span>{place?.id + 1}/{sector['places']?.length}</span>
        </div>
    );

    const affiliations = sector['affiliations']?.map((org: any, index: number) =>
        <div
            key={index}
            style={{
                height: '80%',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between'
            }}
        >
            <Title size='h2'>{org?.name}</Title>
            <span>{org?.description}</span>
        </div>
    );

    const affiliationsSelector = [
        {
            name: 'alcerium',
            active: <ClubSVG height='40px' fill='white' stroke='white' />,
            inactive: <ClubSVG height='40px' fill='none' stroke='white' />,
        },
        {
            name: 'castorix',
            active: <DiamondSVG height='40px' fill='white' stroke='white' />,
            inactive: <DiamondSVG height='40px' fill='none' stroke='white' />,
        },
        // {
        //     name: 'valterre',
        //     active: <ClubSVG height='40px' fill='#050937' stroke='#050937' />,
        //     inactive: <ClubSVG height='40px' fill='none' stroke='#050937' />,
        // },
        {
            name: 'lyrisius',
            active: <SpadeSVG height='40px' fill='white' stroke='white' />,
            inactive: <SpadeSVG height='40px' fill='none' stroke='white' />,
        },
        {
            name: 'lysande',
            active: <HeartSVG height='40px' fill='#050937' stroke='#050937' />,
            inactive: <HeartSVG height='40px' fill='none' stroke='#050937' />,
        },
    ];

    return (
        <>
            <div style={{ height: '60px' }}></div>
            <div
                className='sector'
                style={{
                    minWidth: '1100px',
                    height: '100%',
                    minHeight: '3000px',
                    color: 'var(--text-main)',
                    backgroundImage: `url(${sector['splash']})`,
                    backgroundSize: '100%',
                    backgroundRepeat: 'no-repeat',
                }}
            >
                <div
                    className='sector_title sector_section'
                    style={{ color: `${sector['titleColor'] ?? sector['titleColor']} !important` }}
                >
                    <Title size='h0'>{sector['name']}</Title>
                    <Title size='h2'>{sector['pronunciation']}</Title>
                </div>
                <div className='sector_intro sector_section'>
                    <div className='sector_intro_text sector_section'>
                        <Title size='h2'>{sector['title']}</Title>
                        <span>{sector['intro']}</span>
                    </div>
                </div>
                <div className='sector_places sector_section'>
                    <Slideshow
                        items={places}
                        arrows
                        shape='circle'
                    />
                </div>
                <div className='sector_affiliations sector_section'>
                    <Slideshow
                        items={affiliations}
                        showMarkers
                        markerKey={sector['name']}
                        markers={affiliationsSelector}
                    />
                </div>
                <div className='sector_selector sector_section'>
                    {sector['outro']?.split('\n')?.map((line: string, index: number) =>
                        <span key={index}>{line}</span>
                    )}
                </div>
                <SectorSelector active={sector['name']} />
            </div>
        </>
    )
}

export default Sector;