import React, { useState, useEffect, PropsWithChildren } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import '../../../styles/animate.scss';
import { Arrow } from '../../../assets/index';
import { CharacterConfig } from '../Config';
import { Accordion } from '../../../components';
import './characterSelection.scss';

type CharacterSelectionProps = {
    sector: string,
}

const CharacterSelection = (props: PropsWithChildren<CharacterSelectionProps>) => {
    const {
        sector,
    } = props;

    const [activeChara, setActiveChara] = useState<string>('');
    const [charaSelect, setCharaSelect] = useState<any>([]);

    const onClick = (name: string) => {
        setActiveChara(name);
    }

    useEffect(() => {
        setActiveChara('');

        const charaSelect = CharacterConfig?.filter((character) =>
            character?.current_sector === sector
        )

        if (charaSelect) {
            setCharaSelect(charaSelect);
        }
    }, [sector]);

    useEffect(() => {
        if (!!activeChara) {
            window.scrollTo({ top: 760, behavior: 'smooth' });
        }
    }, [activeChara]);

    AOS.init({
        duration: 1250,
    })

    return (
        <>
            <div className='charaSelect animate_focusInFast'>
                {charaSelect?.map((character: any, index: number) =>
                    <div
                        key={index}
                        className='charaSelect_container'
                        onClick={() => onClick(character.name)}
                    >
                        <div className='charaSelect_icon_container'>
                            <img
                                src={character.icon_back}
                                className={(activeChara === '' && 'charaSelect_icon_back animate_pulse') || (activeChara !== character.name ? 'charaSelect_icon_back charaSelect_icon_inactive animate_pulse' : 'charaSelect_icon_back charaSelect_icon_active animate_pulse')}
                                alt={character.name + 'icon img'}
                            />
                            <img
                                src={character.icon}
                                className={(activeChara === '' && 'charaSelect_icon animate_focusIn charaSelect_icon_active') || (activeChara !== character.name ? 'charaSelect_icon charaSelect_icon_inactive' : 'charaSelect_icon charaSelect_icon_active')}
                                alt={character.name + 'icon img'}
                            />
                            <div className='charaSelect_info' >
                                <h2 className={character.name + 'Active charaSelect_info_name'}>{character.fullname.toUpperCase()}</h2>
                                <span className='charaSelect_info_tagline'>{character.tagline}</span>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {activeChara ? (charaSelect?.map((character: any, index: number) =>
                activeChara === character.name
                &&
                <div className='charaDetails' key={index}>
                    <div
                        className='charaDetails_header_fade'
                        style={{ backgroundImage: `linear-gradient(to bottom, transparent, rgba(var(--${character.name}-color), 1)` }}
                    />
                    <div
                        className='charaDetails_header'
                        style={{ borderTop: `150px solid rgba(var(--${character.name}-color), 1)` }}
                    >
                        <div className='charaDetails_header_container'>
                            <h2 className='charaDetails_header_container_name'>{character.fullname}</h2>
                            <span className='charaDetails_header_container_pronunciation'>{character.pronunciation}</span>
                        </div>
                    </div>
                    <div className='charaDetails_body_container'>
                        <br></br>
                        <div className='charaDetails_body'>
                            <div className='charaDetails_body_display'>
                                <img
                                    src={character.fullbody}
                                    alt={character.name + 'fullbody img'}
                                />
                            </div>
                            <div className='charaDetails_body_info'>
                                <div className='charaDetails_body_info_container'>
                                    <div className='charaDetails_body_info_container_hidden'>
                                        <img
                                            src={character.sector_image}
                                            className='charaDetails_body_info_container_sectorbg'
                                            alt={character.sector + 'logo'}
                                        />
                                    </div>
                                    <div className='charaDetails_body_info_container_more'>
                                        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                                            <div>
                                                {/* <img
                                                    src={character.card}
                                                    className='charaDetails_body_info_container_card'
                                                    alt={character.name + 'card img'}
                                                /> */}
                                                <div className='charaDetails_body_info_summary'>
                                                    {Object.keys(character.attributes).map((keyName, i) => (
                                                        <div className='charaDetails_body_info_summary_att' key={i}>
                                                            <span
                                                                className='charaDetails_body_info_summary_att_highlight'
                                                                style={{ backgroundColor: `rgba(var(--${character.name}-color), 0.4)` }}
                                                            >
                                                                {keyName.replace(/_/g, ' ').toUpperCase()}
                                                            </span>
                                                            <span className='charaDetails_body_info_summary_att_value'>{character.attributes[keyName]}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                            <Accordion
                                                items={CharacterConfig?.find((i) => i.name === activeChara)?.details || []}
                                                overflowHeight='100px'
                                                titleSize='h3'
                                                titleColor={`rgba(var(--${activeChara}-color), 1)`}
                                            />
                                            <div className='toTop'>
                                                <div className='toTop_container'>
                                                    <span>TO TOP</span>
                                                    <img
                                                        src={Arrow}
                                                        className='toTop_arrow'
                                                        onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                                                        alt='arrow'
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )) : <div style={{ margin: '100px' }}></div>}
        </>
    )
}

export default CharacterSelection;