import React, { PropsWithChildren, useState } from 'react';
import { SlideshowButton } from '..';
import './index.scss';

type SlideshowProps = {
    arrows?: boolean,
    items: Array<any>,
    shape?: 'circle' | 'rectangular',
    showMarkers?: boolean,
    markers?: Array<any>,
    markerKey?: string,
}

const Slideshow = (props: PropsWithChildren<SlideshowProps>) => {
    const {
        arrows,
        items,
        shape,
        showMarkers,
        markerKey,
        markers
    } = props;

    const [activeIndex, setActiveIndex] = useState(0);

    const nextItem: any = () => {
        if (activeIndex !== items?.length - 1) {
            setActiveIndex(activeIndex + 1);
        }
        else if (activeIndex === items?.length - 1) {
            setActiveIndex(0);
        }
    }

    const prevItem = () => {
        if (activeIndex !== 0) {
            setActiveIndex(activeIndex - 1);
        }
        else if (activeIndex === 0) {
            setActiveIndex(items?.length - 1);
        }
    }

    const markerItems = markers && markerKey ? markers?.find((i) => i['name'] === markerKey?.toLowerCase()) : null;

    return (
        <div className='slideshow'>
            <div className='slideshow_container'>
                {arrows && <SlideshowButton onSlide={prevItem} direction={'left'} />}
                {items?.map((item, index) =>
                    activeIndex === Number(item['key']) &&
                    <>
                        {shape === 'circle' && <div
                            className='slideshow_slide_container slideshow_slide_container_border animate_spinHalf'
                            style={{
                                width: `${shape === 'circle' && '54vh'}`,
                                height: `${shape === 'circle' && '54vh'}`,
                                borderRadius: `${shape === 'circle' ? '100%' : '10px'}`
                            }}
                        >
                        </div>}
                        <div
                            className='slideshow_slide_container'
                            style={{
                                width: `${shape === 'circle' && '54vh'}`,
                                height: `${shape === 'circle' && '54vh'}`,
                                borderRadius: `${shape === 'circle' ? '100%' : '10px'}`
                            }}
                        >
                            <div
                                key={Number(item['key'])}
                                className={activeIndex === Number(item['key']) ? `slideshow_slide slideshow_slide_animate` : `slideshow_slide`}
                                style={{
                                    borderRadius: `${shape === 'circle' ? '100%' : '10px'}`
                                }}
                            >
                                {item}
                            </div>
                        </div>
                    </>
                )}
                {arrows && <SlideshowButton onSlide={nextItem} direction={'right'} />}
            </div>
            {showMarkers
                ? <div className='slideshow_indices_container'>
                    {Array.from({ length: items?.length })?.map((item, index) => (
                        !!markerItems
                            ? (activeIndex === index
                                ? <div key={index} className='slideshow_markers'>{markerItems['active']}</div>
                                : <div key={index} className='slideshow_markers slideshow_markers_inactive' onClick={() => setActiveIndex(index)}>{markerItems['inactive']}</div>
                            ) : <div
                                key={index}
                                onClick={() => setActiveIndex(index)}
                                className={activeIndex === index ? 'slideshow_indices slideshow_indices_active' : 'slideshow_indices'}
                            />
                    ))}
                </div>
                : <></>
            }
        </div>
    )
}

export default Slideshow;