import React, { PropsWithChildren } from 'react';
import classnames from 'classnames';
import './index.scss';

type TitleProps = {
    color?: string,
    margin?: string,
    size?: 'h0' | 'h1' | 'h2' | 'h3' | 'h4',
    weight?: string,
}

const Title = (props: PropsWithChildren<TitleProps>) => {
    const {
        children,
        color,
        margin,
        size,
        weight,
    } = props;

    const sharedProps = {
        className: classnames(
            'title',
            size ? `size_${size}` : 'size_h4',
        )
    }

    return (
        <div
            {...sharedProps}
            style={{
                margin: `${margin}`,
                color: `${color ? color : 'var(--text-main)'}`,
                fontWeight: `${weight ? weight : 'normal'}`,
            }}
        >
            {children}
        </div>
    );
}

export default Title;
